const seen = new Set();
const output = [];

for (const item of $input.all()) {
  if (!item || !item.json) continue;
  const json = item.json;
  const key = json.link || json.url || json.guid || json.id || json.title;
  if (!key) continue;
  const safeKey = String(key);
  if (seen.has(safeKey)) continue;
  seen.add(safeKey);
  output.push({ json });
}

return output;

// Filter: keep only items with a title and link
const output = [];

for (const item of $input.all()) {
  if (!item || !item.json) continue;
  const j = item.json;
  if (!j.title) continue;
  output.push({ json: j });
}

return output;

// Aggregate: build article list and GPT prompt (max 30 articles)
const items = $input.all() || [];
const articles = [];

for (const item of items) {
  if (!item || !item.json) continue;
  const j = item.json;
  if (!j.title) continue;
  articles.push({
    title: String(j.title || 'Sem título').slice(0, 120),
    link:  String(j.link || j.url || '')
  });
  if (articles.length >= 30) break;
}

if (articles.length === 0) {
  articles.push({ title: 'Nenhuma notícia encontrada', link: '' });
}

const numberedList = articles
  .map((a, i) => (i + 1) + ". " + a.title)
  .join("\n");

const prompt = `Você é um analista de Inteligência Artificial do Inteli Academy.

Analise as seguintes notícias coletadas esta semana:

${numberedList}

Gere um relatório em português com estas 4 seções (use ## antes de cada título):

## Destaques da Semana
As 3 a 5 notícias mais relevantes com um comentário breve de cada.

## Tendências Identificadas
3 padrões ou movimentos observados no conjunto de notícias.

## Oportunidades
2 oportunidades para startups ou projetos que emergem dessas notícias.

## Resumo Executivo
Um parágrafo sintetizando o estado da IA esta semana.`;

return [{
  json: {
    total: articles.length,
    articles,
    prompt
  }
}];

