// Merge GPT: extract GPT text and join with article data from Aggregate
const gptJson = $input.first()?.json || {};

// Extract the report text from the OpenAI response
let gptReport = '';
if (gptJson?.choices?.[0]?.message?.content) {
  gptReport = gptJson.choices[0].message.content;
} else if (gptJson?.message?.content) {
  gptReport = gptJson.message.content;
} else if (typeof gptJson?.text === 'string') {
  gptReport = gptJson.text;
} else {
  gptReport = JSON.stringify(gptJson).slice(0, 800);
}

// Pull the article list and total from the Aggregate node
let articles = [];
let total = 0;
try {
  const agg = $('Aggregate').first()?.json || {};
  articles = agg.articles || [];
  total    = agg.total    || 0;
} catch(e) {}

return [{
  json: { gptReport, articles, total }
}];

const input = $input.first()?.json || {};

const gptReport = (input.gptReport || '').trim() || 'Relatorio nao gerado.';
const total     = input.total    || 0;
const articles  = input.articles || [];

const weekDate = new Date().toLocaleDateString('pt-BR', {
  day: '2-digit', month: 'long', year: 'numeric'
});

// ── Convert markdown-ish GPT output to HTML ──────────────────────────────────
function mdToHtml(text) {
  const lines = text.split('\n');
  let html = '';
  let inList = false;

  for (let raw of lines) {
    const line = raw.trim();

    // Section headings  ## Foo
    if (line.startsWith('## ')) {
      if (inList) { html += '</ul>'; inList = false; }
      html += '<h2 class="rh2">' + esc(line.slice(3)) + '</h2>';
      continue;
    }

    // Sub-headings  ### Foo
    if (line.startsWith('### ')) {
      if (inList) { html += '</ul>'; inList = false; }
      html += '<h3 class="rh3">' + esc(line.slice(4)) + '</h3>';
      continue;
    }

    // Bullet points  - Foo  or  * Foo
    if (/^[-*]\s/.test(line)) {
      if (!inList) { html += '<ul class="rlist">'; inList = true; }
      html += '<li>' + inline(line.slice(2)) + '</li>';
      continue;
    }

    // Numbered list  1. Foo
    if (/^\d+\.\s/.test(line)) {
      if (!inList) { html += '<ul class="rlist">'; inList = true; }
      html += '<li>' + inline(line.replace(/^\d+\.\s/, '')) + '</li>';
      continue;
    }

    // Empty line → paragraph break
    if (line === '') {
      if (inList) { html += '</ul>'; inList = false; }
      html += '<br>';
      continue;
    }

    // Normal paragraph line
    if (inList) { html += '</ul>'; inList = false; }
    html += '<p class="rp">' + inline(line) + '</p>';
  }

  if (inList) html += '</ul>';
  return html;
}

function esc(s) {
  return String(s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function inline(s) {
  return esc(s)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/`(.+?)`/g, '<code>$1</code>');
}
// ─────────────────────────────────────────────────────────────────────────────

const reportHtml  = mdToHtml(gptReport);

const articlesHtml = articles.length > 0
  ? articles.map((a, i) =>
      '<div class="ai">' +
        '<span class="an">' + String(i + 1).padStart(2, '0') + '</span>' +
        (a.link
          ? '<a class="at" href="' + a.link + '" target="_blank">' + esc(a.title) + '</a>'
          : '<span class="at">' + esc(a.title) + '</span>') +
      '</div>'
    ).join('')
  : '<p class="empty">Nenhuma noticia encontrada.</p>';

const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Inteli Academy - AI News | ${weekDate}</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,Helvetica,sans-serif;background:#f5f5f0;color:#1a1a1a;line-height:1.6;padding:32px 16px}
.wrap{max-width:680px;margin:0 auto;background:#fff;border:1px solid #e0e0d8}

/* header */
.hd{padding:32px 40px 24px;border-bottom:3px solid #1a1a1a}
.ht{display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:8px}
.brand{font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:#888;margin-bottom:6px}
.headline{font-size:28px;font-weight:700;line-height:1.1}
.dtag{font-size:11px;color:#fff;background:#1a1a1a;padding:4px 10px;white-space:nowrap;align-self:flex-start;margin-top:4px}

/* stats */
.ss{display:flex;border-bottom:1px solid #e0e0d8}
.sb{flex:1;padding:20px 40px;border-right:1px solid #e0e0d8}
.sb:last-child{border-right:none}
.sn{font-size:36px;font-weight:700;line-height:1}
.sl{font-size:11px;color:#888;text-transform:uppercase;margin-top:4px}

/* body */
.bd{padding:32px 40px}
.sec{margin-bottom:40px}
.slabel{font-size:10px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:#888;margin-bottom:16px;padding-bottom:8px;border-bottom:1px solid #e0e0d8}

/* report */
.rp{font-size:14px;line-height:1.75;color:#333;margin-bottom:10px}
.rh2{font-size:16px;font-weight:700;margin:24px 0 8px;color:#1a1a1a}
.rh3{font-size:14px;font-weight:600;margin:16px 0 6px;color:#333}
.rlist{list-style:none;padding:0;margin:6px 0 12px}
.rlist li{font-size:14px;color:#333;padding:6px 0 6px 14px;border-left:2px solid #1a1a1a;margin-bottom:6px;line-height:1.55}
.rlist li strong{color:#1a1a1a}

/* articles */
.ai{display:flex;align-items:baseline;gap:14px;padding:12px 0;border-bottom:1px solid #f0f0e8}
.ai:last-child{border-bottom:none}
.an{font-size:11px;color:#bbb;min-width:22px;flex-shrink:0}
.at{font-size:13px;color:#1a1a1a;text-decoration:none;font-weight:500;line-height:1.45}
.at:hover{text-decoration:underline}
.empty{font-size:13px;color:#888;font-style:italic}

/* footer */
.ft{border-top:3px solid #1a1a1a;padding:20px 40px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
.fb{font-size:12px;font-weight:600}
.fm{font-size:11px;color:#888}

@media(max-width:600px){
  .hd,.bd,.ft{padding-left:20px;padding-right:20px}
  .ss{flex-direction:column}
  .sb{border-right:none;border-bottom:1px solid #e0e0d8}
  .sb:last-child{border-bottom:none}
}
</style>
</head>
<body>
<div class="wrap">

  <div class="hd">
    <div class="ht">
      <div>
        <div class="brand">Inteli Academy — AI Newsletter</div>
        <div class="headline">AI News<br>Weekly</div>
      </div>
      <div class="dtag">${weekDate}</div>
    </div>
  </div>

  <div class="ss">
    <div class="sb"><div class="sn">${total}</div><div class="sl">Noticias</div></div>
    <div class="sb"><div class="sn">3</div><div class="sl">Fontes</div></div>
    <div class="sb"><div class="sn">GPT</div><div class="sl">Analisado por</div></div>
  </div>

  <div class="bd">

    <div class="sec">
      <div class="slabel">Analise semanal</div>
      <div class="report-wrap">${reportHtml}</div>
    </div>

    <div class="sec">
      <div class="slabel">Todas as noticias — ${total} itens</div>
      ${articlesHtml}
    </div>

  </div>

  <div class="ft">
    <div class="fb">Inteli Academy</div>
    <div class="fm">Gerado via n8n + GPT-4o</div>
  </div>

</div>
</body>
</html>`;

return [{
  json: {
    html,
    subject: 'Inteli Academy - AI News | ' + weekDate + ' | ' + total + ' noticias',
    report: gptReport,
    total
  }
}];
